package practice_002;

public class Pr016_Strings {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		String s="java";
		String s1="  venkatesh  ";
		String v="python";
		System.out.println(s.charAt(0));
		System.out.println(s.concat("oops"));
		System.out.println(s.substring(3));
		System.out.println(s.compareTo(v));
		System.out.println(s.compareToIgnoreCase(v));
		System.out.println(s.contains(v));
		System.out.println(s.length());
		System.out.println(s.toUpperCase());
		System.out.println(s.toLowerCase());
		System.out.println(s.equals("advance java"));
		System.out.println(s.equalsIgnoreCase("JAVa"));
		System.out.println(s1.trim());
		

	}

}
